)


prediction_preview.head(10)

# Create a feature-coefficient table

feature_effects = pd.DataFrame(

    {

        "feature": (

            feature_names

        ),

        "coefficient": (

            model_coefficients

        )

    }

)


# Remove preprocessing prefixes

feature_effects[
    "feature"
] = (

    feature_effects[
        "feature"
    ]

    .str.replace(

        "numerical__",

        "",

        regex=False

    )

    .str.replace(

        "categorical__",

        "",

        regex=False

    )

)


# Calculate odds ratios

feature_effects[

    "odds_ratio"

] = np.exp(

    feature_effects[

        "coefficient"

    ]

)


# Add coefficient direction

feature_effects[

    "association"

] = np.where(

    feature_effects[

        "coefficient"

    ] > 0,

    "Higher Predicted Churn",

    "Lower Predicted Churn"

)


# Calculate absolute coefficient strength

feature_effects[

    "absolute_coefficient"

] = (

    feature_effects[

        "coefficient"

    ]

    .abs()

)


feature_effects = (

    feature_effects

    .sort_values(

        "absolute_coefficient",

        ascending=False

    )

    .reset_index(

        drop=True

    )

)


feature_effects.head(20)

